import{_ as s,o as l,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/251_ca4a6d02-4190-49a2-9b93-2535d141ff37.BmI9gSzm.png",i="/assets/256_9ec9adb2-8e6e-464d-bf07-662da7956b1c.3tQOd4Is.png",m=JSON.parse('{"title":"物理服务机器重装系统","description":"","frontmatter":{"title":"物理服务机器重装系统"},"headers":[],"relativePath":"ops-knowledge-base/dedicated-server/reinstall-os.md","filePath":"ops-knowledge-base/dedicated-server/reinstall-os.md","lastUpdated":1788259091000}'),e={name:"ops-knowledge-base/dedicated-server/reinstall-os.md"};function a(g,t,p,d,c,_){return l(),o("div",null,[...t[0]||(t[0]=[r('<p>在使用服务器的过程中，您可能会遇到需要更换操作系统、修复系统故障或重新规划磁盘分区等情况。后台面板的重装系统功能，允许您便捷地对服务器操作系统进行重新安装，满足多样化的使用需求。</p><h2 id="一、操作入口" tabindex="-1">一、操作入口 <a class="header-anchor" href="#一、操作入口" aria-label="Permalink to &quot;一、操作入口&quot;">​</a></h2><ol><li>登录平台，进入客户中心，下方**“我的订单”** 点击 **“物理服务器”**。或者在 **“产品管理”** 点击 **“物理服务器”**，根据机器所在地区和状态筛选。</li><li>在 “管理产品” 页面，您可以看到服务器的基本信息。点击上方的 <strong>“服务器信息”</strong> 标签，在操作按钮区域找到 <strong>“重装系统”</strong> 按钮。</li></ol><p><img src="'+n+'" alt=""></p><h2 id="二、操作步骤" tabindex="-1">二、操作步骤 <a class="header-anchor" href="#二、操作步骤" aria-label="Permalink to &quot;二、操作步骤&quot;">​</a></h2><ol><li><p><strong>点击 “重装系统” 按钮</strong>：点击后，会弹出 “重装系统” 窗口。</p></li><li><p><strong>配置重装选项</strong>：</p><ul><li><strong>选择操作系统</strong>：在 “操作系统” 下拉菜单中，根据您的业务需求，选择合适的操作系统版本。</li><li><strong>设置密码</strong>：在 “密码” 输入框中，设置操作系统的登录密码。您也可以点击密码输入框右侧的 “随机” 按钮，由系统自动生成一个强密码。</li><li><strong>设置端口</strong>：在 “端口” 输入框中，设置远程连接服务器的端口号，同样支持点击 “随机” 按钮生成随机端口。</li></ul></li></ol><ul><li><p><strong>选择分区类型（windows）</strong>：</p><ul><li><p><strong>全盘格式化</strong>：选择该选项，将对服务器的整个硬盘进行格式化操作，会清除硬盘上的所有数据，请谨慎选择。一般在您需要彻底清理服务器数据，或者更换不同类型的操作系统时使用。</p></li><li><p><strong>第一分区格式化</strong>：仅格式化服务器的第一个分区，其他分区的数据将被保留。适用于您仅需重新安装操作系统，而其他分区数据仍需保留的情况。</p></li><li><p><strong>选择分区方式</strong>：</p><ul><li><strong>默认分区</strong>：系统将按照预设的标准方式对硬盘进行分区（默认分区系统为100G）</li><li><strong>自定义分区</strong>：如果您对磁盘分区有特殊要求，如自定义每个分区的大小、文件系统类型等，可以选择此选项，手动设置分区参数。</li></ul></li></ul></li><li><p><strong>数据备份提示</strong>：在操作前，请务必仔细阅读 “重装系统所有数据丢失，请确认已备份数据” 提示。若您已对重要数据进行备份，勾选该提示前的复选框。</p></li><li><p><strong>选择分区类型（linux）</strong>：</p><ul><li>Linux无法保留数据重装，确认重装即认可全盘格式化，无法恢复，请提前进行数据备份。</li></ul></li><li><p><strong>选择分区方式</strong>：</p><ul><li><strong>默认分区</strong>：系统将按照预设的标准方式对硬盘进行分区（默认分区 /为最大空间）</li><li><strong>附加配置</strong>：提供一些额外的分区配置选项，以满足特定的使用需求。</li><li><strong>自定义分区</strong>：如果您对磁盘分区有特殊要求，如自定义每个分区的大小、文件系统类型等，可以选择此选项，手动设置分区参数。</li></ul></li><li><p><strong>数据备份提示</strong>：在操作前，请务必仔细阅读 “重装系统所有数据丢失，请确认已备份数据” 提示。若您已对重要数据进行备份，勾选该提示前的复选框。</p></li></ul><p><img src="'+i+'" alt=""></p><ol start="3"><li><strong>确认重装</strong>：在完成上述所有配置后，点击 <strong>“确认重装”</strong> 按钮，系统将开始执行重装系统操作。在此期间，服务器将无法正常使用，您可以在 “产品详情” 页面查看服务器安装状态，等待重装完成。</li><li><strong>登录信息</strong>：重装完成后，在“<strong>软件信息</strong>”里，可查看重装后的登录信息，点击“<strong>*</strong>”可以查看登录密码</li></ol><h2 id="三、注意事项" tabindex="-1">三、注意事项 <a class="header-anchor" href="#三、注意事项" aria-label="Permalink to &quot;三、注意事项&quot;">​</a></h2><ol><li><strong>数据备份</strong>：在进行重装系统操作前，务必对服务器上的重要数据进行备份，以免造成数据丢失。</li><li><strong>等待过程</strong>：重装系统所需时间会根据服务器性能、网络状况以及操作系统安装复杂度而有所不同，请耐心等待。</li></ol>',11)])])}const h=s(e,[["render",a]]);export{m as __pageData,h as default};
